import { describe, expect, it } from "vitest";
import { hashOpaqueToken, hashPassword, LEGACY_BCRYPT_SALT, verifyPassword } from "./local-password";

describe("local password primitives", () => {
  it("verifies the original Python/passlib format without resetting the password", async () => {
    // Generated by the legacy backend's CryptContext, not this verifier.
    const hash = "$2b$12$kLjW42l5t0ucgpA7XdCPouJ5jTwKiw9hT0xqLogCkzZIsMVpiZkWq";
    await expect(verifyPassword("LegacyPreserved#2026", LEGACY_BCRYPT_SALT, hash)).resolves.toBe(true);
    await expect(verifyPassword("WrongPassword#2026", LEGACY_BCRYPT_SALT, hash)).resolves.toBe(false);
    await expect(verifyPassword("LegacyPreserved#2026", "unmarked", hash)).resolves.toBe(false);
    await expect(verifyPassword("LegacyPreserved#2026", LEGACY_BCRYPT_SALT, hash.replace("$12$", "$31$"))).resolves.toBe(false);
  });

  it("stores a salted derived password and verifies it without plaintext", async () => {
    const first = await hashPassword("IgloDemo#2026");
    const second = await hashPassword("IgloDemo#2026");

    expect(first.hash).not.toBe("IgloDemo#2026");
    expect(first.salt).not.toBe(second.salt);
    expect(first.hash).not.toBe(second.hash);
    await expect(verifyPassword("IgloDemo#2026", first.salt, first.hash)).resolves.toBe(true);
    await expect(verifyPassword("wrong-password", first.salt, first.hash)).resolves.toBe(false);
  });

  it("hashes opaque tokens deterministically", () => {
    expect(hashOpaqueToken("refresh-token")).toHaveLength(64);
    expect(hashOpaqueToken("refresh-token")).toBe(hashOpaqueToken("refresh-token"));
    expect(hashOpaqueToken("refresh-token")).not.toBe(hashOpaqueToken("another-token"));
  });
});
